from math import exp


def sigmoid(score):
    if score >= 0:
        return 1 / (1 + exp(-score))
    z = exp(score)
    return z / (1 + z)


print(sigmoid(-0.3), sigmoid(-1000), sigmoid(1000))

from pathlib import Path
import hashlib, json

folder = Path("build/chapter-14-artifacts")
if (folder / "checksums.json").exists():
    hashes = json.loads((folder / "checksums.json").read_text())
    assert all(
        hashlib.sha256((folder / name).read_bytes()).hexdigest() == digest
        for name, digest in hashes.items()
    )
    print("Artifact bytes match the recorded manifest")
else:
    print("Run the documented CLI with --artifact-dir to generate artifacts first")

groups = {"A": {"tp": 8, "fn": 2}, "B": {"tp": 2, "fn": 3}}
recalls = {}
for group, counts in groups.items():
    positives = counts["tp"] + counts["fn"]
    # Missing positives means undefined recall, not evidence of zero performance.
    recalls[group] = counts["tp"] / positives if positives else None
print(recalls["A"], recalls["B"], recalls["A"] - recalls["B"])

def validate_order(incoming, expected):
    if incoming != expected:
        raise ValueError("feature order mismatch")


try:
    validate_order(["pH", "alcohol"], ["alcohol", "pH"])
except ValueError as error:
    print(error)

